/** Generated by the NeuralCommons App Generator (layer: frontend). */

import { apiGet } from "../../lib/api";

export default async function Provenance({ searchParams }) {
  const cid = searchParams?.cid;
  const result = cid ? await apiGet(`/provenance/${encodeURIComponent(cid)}`) : null;

  return (
    <main>
      <section className="panel">
        <h2>Provenance chain</h2>
        {!cid ? (
          <p className="muted">Add ?cid=&lt;instrument cid&gt; to walk the chain to genesis.</p>
        ) : !result.ok ? (
          <p className="muted">No instrument with that CID ({result.error}).</p>
        ) : (
          <ol>
            {result.data.chain.map((row) => (
              <li key={row.cid}>
                <strong>{row.instrument}</strong> · {row.trust}
                <div className="mono muted">{row.cid}</div>
              </li>
            ))}
          </ol>
        )}
      </section>
    </main>
  );
}
